function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
(async () => {
  const tw = require("tailwindcss");
  if (typeof tw.__unstable__loadDesignSystem !== "function") broken("__unstable__loadDesignSystem is not exported");
  const ds = await tw.__unstable__loadDesignSystem("@tailwind utilities;\n", { base: "/tmp" });
  if (!ds || typeof ds.canonicalizeCandidates !== "function") broken("canonicalizeCandidates is not available");
  if (ds.candidatesToCss(["-left-[9rem]"])[0] == null) broken("-left-[9rem] does not compile");
  const out = ds.canonicalizeCandidates(["-left-[9rem]"]);
  if (!Array.isArray(out) || out.length !== 1) broken("unexpected result " + JSON.stringify(out));
  if (out[0] === "-left-[9rem]") symptom("canonicalizeCandidates kept -left-[9rem] instead of left-[-9rem]");
  if (out[0] !== "left-[-9rem]") broken("canonicalizeCandidates gave " + out[0]);
  console.log("OK: -left-[9rem] canonicalizes to left-[-9rem]");
})().catch((e) => broken(String((e && e.stack) || e)));

